// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 warp1, uint256 warp2, uint256 blockNum2) public {
        vm.assume(warp1 > 0);
        vm.assume(warp2 > 0);
        vm.assume(warp2 != warp1);
        uint256 earlier = warp1 < warp2 ? warp1 : warp2;
        uint256 later = warp1 > warp2 ? warp1 : warp2;

        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        vm.warp(earlier);
        vm.roll(1);
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        vm.warp(later);
        vm.roll(blockNum2);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        assertEq(c.pastBlockTime(), later, "pastBlockTime must equal second call's block.timestamp");
    }
}
